node -e 'const fs = require("fs")
const s = fs.readFileSync("lib/commerce/split-refund.ts", "utf8")
if (/refund_reversal_cents:\s*target,\s*reversal_attempts:\s*0/.test(s)) { console.error("SCAN-649: raising a reversal target resets reversal_attempts to 0, which undoes the compare-and-set claim of a worker already calling Stripe; a second refund then reverses the same seller again under a different key."); process.exit(1) }
const m = /export function reversalIdempotencyKey\(([^)]*)\)/.exec(s)
if (!m || m[1].split(",").length < 4) { console.error("SCAN-649: the reversal idempotency key is fixed to (row, from, to), so a Stripe error saved under that key (e.g. an empty connected balance) answers every retry for 24h and the reconciler gives up after 8 attempts: that seller share is never reversed and the platform pays it."); process.exit(1) }
'
